import math

def apy_from_credit(principal, interest, days=31):
    return (1 + interest/principal)**(365/days) - 1

def credit_from_apy(principal, apy, days=31):
    return principal * ((1+apy)**(days/365) - 1)

for p,i in [(30000,63.75),(60000,327.5)]:
    apy=apy_from_credit(p,i)
    print('principal',p,'interest',i,'apy',apy*100)

for apy in [0.025,0.027,0.03,0.0325,0.0635,0.065,0.0662,0.0685]:
    print('apy',apy*100,'bronze credit',credit_from_apy(30000,apy),'goldplus credit',credit_from_apy(60000,apy))
